function CatHouseMatchPopup:InitData()
    local parameters   = self.controller.Argument.parameters
    local deliveryId   = checkNumber(parameters.deliveryId)
    local isFromInteraction   = checkBool(parameters.isFromInteraction)

    ---@type CatHouseComponent
    local component = GameUtils.GetEntityCompByType(ECSComponentType.Constants.CatHouseComponent, Constants.CatHouseEntityId)
    ---@type CatHouseHomeDojo
    local catHouseHomeDojo = component:GetCatHouseHomeDojo()
    local deliveryList = catHouseHomeDojo.deliveryList
    local deliveryData
    for i, v in ipairs(deliveryList) do
        if checkNumber(v.deliveryId )== deliveryId then
            deliveryData = v
            break
        end
    end

    --- myCatData:table 与 catHouseHomeDojo.catList 中单条数据一致
    local myCatData    = KCookie.Get(CookieMyCatDataName)
    if myCatData then
        KCookie.Set(CookieMyCatDataName)
    else
        local playerCatId = checkNumber(deliveryData.playerCatId)
        if playerCatId > 0 then
            myCatData = component:GetCatDataById(playerCatId)
        end
    end

    local matchStatus = MatchStatus.SelectCat
    --- otherCatData:table 与 catHouseHomeDojo.catList 中单条数据一致
    local otherCatData, otherCatOwnerInfo, consumePrice, matchType
    local otherCatInfo = KCookie.Get(CookieOtherCatInfoName)
    if otherCatInfo then
        otherCatData, otherCatOwnerInfo, consumePrice, matchType = otherCatInfo.otherCatData, otherCatInfo.otherCatOwnerInfo, otherCatInfo.consumePrice, otherCatInfo.matchType
        KCookie.Set(CookieOtherCatInfoName)
    elseif checkNumber(deliveryData.status) == 1 then
        otherCatData = deliveryData.friendCat
        otherCatOwnerInfo = deliveryData.friend
        matchStatus = MatchStatus.Inviting
        if otherCatData then
            matchType = MatchType.FriendMatchComplete
        end
    end

    if myCatData and otherCatData and matchStatus == MatchStatus.SelectCat and matchType ~= MatchType.FriendMatchComplete then
        matchStatus = matchType == MatchType.FriendMatch and MatchStatus.Invite or MatchStatus.Match
    end
    self.matchType   = matchType
    self.matchStatus = matchStatus
    self.deliveryId = deliveryId
    self.deliveryData = deliveryData
    self.myCatData, self.otherCatData, self.otherCatOwnerInfo, self.consumePrice = myCatData, otherCatData, otherCatOwnerInfo, consumePrice

    self.isFromInteraction = isFromInteraction
    --- 孵化消耗道具id
    self.hatchConsumeId = checkNumber(CfUtils.GetCfVo(AutoIds.IdSetting1903, "BaseArgVo", ConstantsCatHouse.Params.HatchConsumeId).num)
    ---集会中使用货币id
    self.rallyGoodsId = checkNumber(CfUtils.GetCfVo(AutoIds.IdSetting1903, "BaseArgVo", ConstantsCatHouse.Params.RallyGoodsId).num)
end


