function CatHouseMatchPopup:FreshRootLeftOrRightAnimation(isFirst)
    local animationNameHash
    if self.myCatData and self.otherCatData then
        animationNameHash = LeftAndRightHash
    elseif self.myCatData then
        animationNameHash = LeftHash
    elseif self.otherCatData then
        animationNameHash = RightHash
    else
        animationNameHash = DefaultHash
    end
    if animationNameHash then
        self.Root:Play(animationNameHash)
    end
    self.InviteGroup.alpha = (self.myCatData and self.otherCatData) and 1 or 0.5
    ---@type CatHouseMatchPopupInviteGroup
    local env = CfUtils.GetLuaScr(self.InviteGroup, CatHouseMatchPopupInviteGroupEnvPath)
    if isNull(env) then return end
    env:SetButtonStatus(self.myCatData, self.otherCatData)
end


