        KCookie.Set(CookieMyCatDataName, self.myCatData)
    end
    if self.otherCatData then
        KCookie.Set(CookieOtherCatInfoName, {otherCatData = self.otherCatData, otherCatOwnerInfo = self.otherCatOwnerInfo, consumePrice = self.consumePrice, matchType = self.matchType})
    end
end

---RequestCatHouseRallyAsk
---公共直接配对
function CatHouseMatchPopup:RequestCatHouseRallyAsk(consume)
    local playerCatId = self.myCatData.id
    local deliveryId  = self.deliveryId
    GameUtils.Request(Interfaces.CatHouseRallyAsk, {
        playerCatId = playerCatId,
        rallyPlayerId = self.otherCatOwnerInfo.playerId,
        rallyPlayerCatId = self.otherCatData.id,
        deliveryId = deliveryId,
        rallyPrice = self.consumePrice
    }, function (request, response)
        if checkNumber(response.errCode) ~= 0 then return end

        GoodsUtils.DrawRewards(consume)
        -------------------------------
        ---1. 处理数据
        ---@type CatHouseComponent
        local component = GameUtils.GetEntityCompByType(ECSComponentType.Constants.CatHouseComponent, Constants.CatHouseEntityId)

        ---1.1 更新孵化次数
        local catData = component:GetCatDataById(playerCatId)
        catData.deliveryRemainTimes = checkNumber(catData.deliveryRemainTimes) - 1

        --- CatHouseMgr 中 _catCDData 直接引用了 catList的 status 所以直接加状态 就好了
        ---1.2 将配对的猫变为 恢复状态
        local remainTime = checkNumber(CfUtils.GetCfVo(AutoIds.IdSetting1903, "BaseArgVo", ConstantsCatHouse.Params.HatchRecoverSeconds).num)
        component:UpdateCDData(playerCatId, ConstantsCatHouse.CatStatus.Recovering, remainTime)

        ---1.3 将新增的孵化状态的猫插入 catList
        local data = response.data
        catData = data.cat
        component:AddCatData(catData)
        --print(table.toString(component:GetCDDataById(catData.id)))

        ---1.4 更新培育列表数据
        local newPlayerCatId = catData.id
        --print("checkNumber(catData.status[ConstantsCatHouse.CatStatus.Hatching])", checkNumber(catData.status[ConstantsCatHouse.CatStatus.Hatching]))
        component:SetDeliveryData(deliveryId, {
            deliveryId = deliveryId,
            playerCatId = playerCatId,
            childPlayerCatId = newPlayerCatId,
            status =  ConstantsCatHouse.CatCultivationType.Hatching,
            remainTime = checkNumber(catData.status[ConstantsCatHouse.CatStatus.Hatching])
        })

        ---1.5 更新培育红点
        component:UpdateDeliveryRedPoint()
        -------------------------------
        ---2. 关闭当前界面并弹出配对成功界面
        cs_coroutine.start(function()
            cs_coroutine.yield_return(UIModule.BackDialog())
            --- 2.1 弹出配对成功界面
            UIModule.OpenDialog({ id = Constants.UITypeIds.CatHouseMatchSuccessPopup, parameters = { catId = newPlayerCatId } })
        end)

    end)
end

---RequestCatHouseFriendAsk
---向好友申请配对
function CatHouseMatchPopup:RequestCatHouseFriendAsk(consume)
    local playerCatId = self.myCatData.id
    local deliveryId  = self.deliveryId
    GameUtils.Request(Interfaces.CatHouseFriendAsk, {
        playerCatId = playerCatId,
        friendId = self.otherCatOwnerInfo.friendId,
        friendCatId = self.otherCatData.id,
        deliveryId = deliveryId,
    }, function (request, response)
        if checkNumber(response.errCode) ~= 0 then return end
        GoodsUtils.DrawRewards(consume)
        -------------------------------
        ---1. 处理数据
        ---@type CatHouseComponent
        local component = GameUtils.GetEntityCompByType(ECSComponentType.Constants.CatHouseComponent, Constants.CatHouseEntityId)

        ---1.1 将配对的猫变为 请求中
        local remainTime = checkNumber(CfUtils.GetCfVo(AutoIds.IdSetting1903, "BaseArgVo", ConstantsCatHouse.Params.FriendMatchSeconds).num)
        component:UpdateCDData(playerCatId, ConstantsCatHouse.CatStatus.Waiting, remainTime)

        self.otherCatOwnerInfo.playerId = self.otherCatOwnerInfo.friendId
        ---1.2 更新培育列表数据
        component:SetDeliveryData(checkNumber(deliveryId), {
            deliveryId = deliveryId,
            status =  ConstantsCatHouse.CatCultivationType.FriendsConfirming,
            remainTime = remainTime,
            friend = self.otherCatOwnerInfo,
            friendCat = self.otherCatData,
            playerCatId = playerCatId
        })

        -------------------------------
        ---2. 关闭界面
        self:OnClickBtnCloseAction()
    end)
end

function CatHouseMatchPopup:RequestCatHouseFriendCancel()
    local deliveryId  = self.deliveryId
    GameUtils.Request(Interfaces.CatHouseFriendCancel, {
        deliveryId = deliveryId,
    }, function (request, response)
        if checkNumber(response.errCode) ~= 0 then return end
        ------------------------
        --- 1.处理数据
        --- 1.1  更新奖励
        local rewards = response.data.rewards
        GoodsUtils.DrawRewards(rewards)

        local playerCatId = self.deliveryData.playerCatId
        --- 1.2 移除倒计时相关数据
        ---@type CatHouseComponent
        local component = GameUtils.GetEntityCompByType(ECSComponentType.Constants.CatHouseComponent, Constants.CatHouseEntityId)
        component:UpdateCDData(playerCatId, ConstantsCatHouse.CatStatus.Waiting)

        --- 1.3 移除 deliveryList 数据
        component:ClearDeliveryDataById(deliveryId)

        -------------------------------
        ---2. 关闭界面
        self:OnClickBtnCloseAction()

        -------------------------------
        ---3. 弹出提示
        GameUtils.Toast(localize("已取消邀请"))

        -------------------------------
        ---4. 弹出奖励
        UIModule.OpenDialog({ id = Constants.UITypeIds.UICommonRewardPop, parameters = { rewards = rewards } })

    end)
end

function CatHouseMatchPopup:CheckAddListener()
    if self.deliveryData and (self.deliveryData.status == CatCultivationType.FriendsConfirming or self.deliveryData.status == CatCultivationType.Hatching) then
        self:AddListener()
    end
end

function CatHouseMatchPopup:AddListener()
    self.__EventCatHouseTimeChange = Events.AddListener(CatHouseTimeChange, Bind(self, self.OnEventCatHouseTimeChange))
end
function CatHouseMatchPopup:RemoveListener()
    if self.__EventCatHouseTimeChange then
        Events.RemoveListener(CatHouseTimeChange, self.__EventCatHouseTimeChange)
        self.__EventCatHouseTimeChange = nil
    end
end

function CatHouseMatchPopup:AddListenerGeneRateUpCDChange(func)
    if self.__EventGeneRateUpCDChange then return end
    self.__EventGeneRateUpCDChange = Events.AddListener(CatHouseGeneRateUpCDChange, func)
end

function CatHouseMatchPopup:RemoveListenerGeneRateUpCDChange()
    if self.__EventGeneRateUpCDChange then
        Events.RemoveListener(CatHouseGeneRateUpCDChange, self.__EventGeneRateUpCDChange)
        self.__EventGeneRateUpCDChange = nil
    end
end

--- PopupStore
--- 弹出商店
---@param goodsId number
---@param num     number
---@param goodsVo GoodsVo
---@return boolean 是否弹窗成功
function CatHouseMatchPopup:PopupStore(goodsId, num, goodsVo)
    if GoodsUtils.GetThingNo(goodsId) >= num then
        return false
    end
    self:SaveCookie()
    ---商城按钮点击的逻辑
    local StoreUtils = import('Game.UI.Store.StoreUtils')
    ---@type StoreConstants
    local StoreConstants = import('Game.UI.Store.StoreConstants')
    StoreUtils.OpenStoreBySecondConfirm(localize("调查官拥有的_name_数量不足", {_name_ = goodsVo.name}), localize("是否前往商店购买？"), StoreConstants.OpenIds.Supply, {
        {id = Constants.UITypeIds.CatHouseMatchPopup}
    })
    return true
end

