    end)
end

function CatHouseMatchPopup:OnClickBtnInviteAction()
    --- 孵化消耗道具id
    local goodsId = checkNumber(CfUtils.GetCfVo(AutoIds.IdSetting1903, "BaseArgVo", ConstantsCatHouse.Params.HatchConsumeId).num)
    --- 孵化消耗道具数量
    local num     = checkNumber(CfUtils.GetCfVo(AutoIds.IdSetting1903, "BaseArgVo", ConstantsCatHouse.Params.HatchConsumeNum).num)

    local consumes = {
        {goodsId = goodsId, goodsNum = num}
    }

    if self.matchStatus == MatchStatus.Invite then
        local goodsVo = GoodsConfMgr:GetInstance():GetGoodsVoById(goodsId)
        if self:PopupStore(goodsId, num, goodsVo) then
            return
        end

        local seconds = checkNumber(CfUtils.GetCfVo(AutoIds.IdSetting1903, "BaseArgVo", ConstantsCatHouse.Params.FriendMatchSeconds).num)
        GameUtils.SecondConfirm(localize("是否消耗_name_x_num_，进行配对", {_name_ = goodsVo.name,_num_ = num}), function()
            local consume, errTips = GoodsUtils.CheckGoodConsume(consumes)
            if errTips then
                GameUtils.Toast(errTips)
                return
            end
            self:RequestCatHouseFriendAsk(consume)
        end, nil, localize("好友确认后开始培育，若被拒绝将返还所有配对消耗"), 1, nil, nil,
                localize("邀请时间：_num_", {_num_ = CfUtils.GetTimeHMS2(seconds)}))

    elseif self.matchStatus == MatchStatus.Match then
        local goodsVo  = GoodsConfMgr:GetInstance():GetGoodsVoById(goodsId)
        if self:PopupStore(goodsId, num, goodsVo) then
            return
        end
        local goodsId1 = checkNumber(CfUtils.GetCfVo(AutoIds.IdSetting1903, "BaseArgVo", ConstantsCatHouse.Params.RallyGoodsId).num)
        table.insert(consumes, {goodsId = goodsId1, goodsNum = self.consumePrice})
        local goodsVo1 = GoodsConfMgr:GetInstance():GetGoodsVoById(goodsId1)
        local consume, errTips = GoodsUtils.CheckGoodConsume(consumes)
        if errTips then
            GameUtils.Toast(errTips)
            return
        end
        GameUtils.SecondConfirm(localize("是否消耗_name_x_num_和_name1_x_num1_，进行配对", {_name_ = goodsVo.name, _num_ = num, _name1_ = goodsVo1.name, _num1_ = self.consumePrice}), function()
            self:RequestCatHouseRallyAsk(consume)
        end, nil, nil, 1, nil, nil)

    elseif self.matchStatus == MatchStatus.SelectCat then
        GameUtils.Toast(localize("请先选择主体与副体猫咪"))

    elseif self.matchType == MatchType.FriendMatchComplete then
        GameUtils.SecondConfirm(localize("是否取消配对"), function()
            self:RequestCatHouseFriendCancel()
        end)

    end
end

function CatHouseMatchPopup:OnClickBtnResultEstimateAction()
    local myCatData    = self.myCatData
    local otherCatData = self.otherCatData
    if myCatData == nil or otherCatData == nil then
        GameUtils.Toast(localize("请先选择主体与副体猫咪"))
        return 
    end
    self:SaveCookie()
    UIModule.OpenDialog({ id = Constants.UITypeIds.CatHouseResultEstimateDialog, parameters = { myCatData = myCatData, otherCatData = otherCatData } }, {
        {id = Constants.UITypeIds.CatHouseMatchPopup}
    })

end

function CatHouseMatchPopup:OnEventCatHouseTimeChange()
    if self.deliveryData and (self.deliveryData.status == CatCultivationType.FriendsConfirming or self.deliveryData.status == CatCultivationType.Hatching) then
        self:FreshCountDown()
    else
        self:RemoveListener()
        self:OnClickOtherCatBtnCloseAction()
        self:FreshInviteGroup()
    end
end

function CatHouseMatchPopup:HandleGeneRateUp()
    CatHouseMgr:GetInstance():CheckGeneRateUpIsOpen(Bind(self, self.SetBtnGeneRateUp))
end

function CatHouseMatchPopup:SetBtnGeneRateUp(dataActivity)
    local endTime = checkNumber(dataActivity.endTime)
    local transBtnGeneRateUp = self.controller.transform:Find("Root/Container/BtnProbabilityUp")
    if isNull(transBtnGeneRateUp) then return end
    local goBtnGeneRateUp = transBtnGeneRateUp.gameObject
    KTool.SetActive(goBtnGeneRateUp, endTime > 0)
    if endTime <= 0 then return end
    CatHouseMgr:GetInstance():GeneRateUpReq(dataActivity, function(themeData, activityData)
        local transImgIcon = transBtnGeneRateUp:Find("AnimRoot/ImgIcon")
        if not IsNull(transImgIcon) then
            local icon = KTool.GetOrAddComponent(transImgIcon.gameObject, typeof(CS.Engine.UI.RawImageAlterable))
            xTry(function() 
                local pathStrings = string.split2(themeData.picture, ":")
                local path = CS.GameUtils.GetCombineResourceDirPath(checkInt(pathStrings[1]), pathStrings[2], ".png")
                icon:LoadSprite(checkString(path))
            end)
        end
        
        if not isNull(CatHouseMgr:GetInstance().timerGeneRateUp) then
            local transRemainTime = transBtnGeneRateUp:Find("AnimRoot/RemainTime/Layout/Text")
            if not IsNull(transRemainTime) then
                local txtRemain = KTool.GetOrAddComponent(transRemainTime.gameObject, typeof(CS.UnityEngine.UI.Text))
                local timeNow = CatHouseMgr:GetInstance().timerGeneRateUp.CountTimes 
                txtRemain.text = localize("剩余_time_", { _time_ = checkString(CfUtils.GetTimeHMS(timeNow))})

                self:AddListenerGeneRateUpCDChange(function (count)
                    if count <= 0 then
                        self:HandleGeneRateUp()
                    else
                        txtRemain.text = localize("剩余_time_", { _time_ = checkString(CfUtils.GetTimeHMS(count))})
                    end
                end)

                -- CatHouseMgr:GetInstance().timerGeneRateUp.OnCd = function(count)
                --     if count <= 0 then   -- 结束
                --         self:HandleGeneRateUp()
                --     else
                --         txtRemain.text = localize("剩余_time_", { _time_ = checkString(CfUtils.GetTimeHMS(count))})
                --     end
                -- end
            end
        end
        
        CS.Engine.UI.UIEventProxy.Create(goBtnGeneRateUp).onPointerClick = function()
            UIModule.OpenDialog({id = Constants.UITypeIds.CatHouseProbabilityUpDialog, 
                                 parameters = { serviceData = themeData, activityData = activityData } })
        end
    end)
end

---------------------------------------------------
--- handler end --
---------------------------------------------------

return CatHouseMatchPopup